  source = "./a"
}
module "m" {
  source = "./m"
  l = module.a.v
}

files.m/main.tf:
variable "l" {
  type = list(object({n=string, o=optional(string, "z")}))
}
output "names" {
  value = concat(["s0-${var.l[0].o}"], [for x in toset([for x in [for o in var.l : "${o.n}-${o.o}"] : tostring(x)]) : "e0-${x}"], [for x in [for o in var.l : "${o.n}-${o.o}"] : "c0-${x}"], [for x in toset([for x in [for o in var.l : o.n] : tostring(x)]) : "e1-${x}"], [for x in [for o in var.l : o.n] : "c1-${x}"])
}

files.m/r.tf:
resource "aws_sqs_queue" "s0" {
  name = "s0-${var.l[0].o}"
}
resource "aws_sqs_queue" "e0" {
  for_each = toset([for x in [for o in var.l : "${o.n}-${o.o}"] : tostring(x)])
  name = "e0-${each.value}"
}
resource "aws_sqs_queue" "c0" {
  count = length([for o in var.l : "${o.n}-${o.o}"])
  name = "c0-${[for o in var.l : "${o.n}-${o.o}"][count.index]}"
}
resource "aws_sqs_queue" "e1" {
  for_each = toset([for x in [for o in var.l : o.n] : tostring(x)])
  name = "e1-${each.value}"
}
resource "aws_sqs_queue" "c1" {
  count = length([for o in var.l : o.n])
  name = "c1-${[for o in var.l : o.n][count.index]}"
}

