files.n/main.tf:
variable "l" {
  type = list(number)
}
output "names" {
  value = concat(["s0-${var.l[2]}"], [for x in toset([for x in [for x in var.l : x] : tostring(x)]) : "e0-${x}"], [for x in [for x in var.l : x] : "c0-${x}"], [for x in toset([for x in sort([for x in var.l : tostring(x)]) : tostring(x)]) : "e1-${x}"], [for x in sort([for x in var.l : tostring(x)]) : "c1-${x}"])
}

files.n/r.tf:
