  name = "s0-${var.l[2]}"
}
resource "aws_sqs_queue" "e0" {
  for_each = toset([for x in [for x in var.l : x] : tostring(x)])
  name = "e0-${each.value}"
}
resource "aws_sqs_queue" "c0" {
  count = length([for x in var.l : x])
  name = "c0-${[for x in var.l : x][count.index]}"
}
resource "aws_sqs_queue" "e1" {
  for_each = toset([for x in sort([for x in var.l : tostring(x)]) : tostring(x)])
  name = "e1-${each.value}"
}
resource "aws_sqs_queue" "c1" {
  count = length(sort([for x in var.l : tostring(x)]))
  name = "c1-${sort([for x in var.l : tostring(x)])[count.index]}"
}

